using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalFountainFlowWater{
static FinalFountainFlowWater(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalFountainFlowWater.request")||EditorApplication.isCompiling)return;File.Delete("FinalFountainFlowWater.request");Run();}
class Build{public List<Vector3> p=new List<Vector3>(),n=new List<Vector3>();public List<Vector2> uv=new List<Vector2>(),info=new List<Vector2>(),plot=new List<Vector2>(),host=new List<Vector2>();public List<Color> color=new List<Color>();public List<int> stone=new List<int>(),water=new List<int>();
public void Tube(Func<float,Vector3> point,float radius,int sides,int steps){for(int j=0;j<steps;j++){float t=j/(float)steps,u=(j+1)/(float)steps;var a=point(t);var b=point(u);var axis=(b-a).normalized;var side=Vector3.Cross(axis,Mathf.Abs(axis.y)>.9f?Vector3.right:Vector3.up).normalized;var across=Vector3.Cross(axis,side).normalized;for(int k=0;k<sides;k++){float x=k*Mathf.PI*2/sides,y=(k+1)*Mathf.PI*2/sides;var nx=side*Mathf.Cos(x)+across*Mathf.Sin(x);var ny=side*Mathf.Cos(y)+across*Mathf.Sin(y);float r0=radius*(1-t*.32f),r1=radius*(1-u*.32f);int i=p.Count;p.AddRange(new[]{a+nx*r0,a+ny*r0,b+ny*r1,b+nx*r1});n.AddRange(new[]{nx,ny,ny,nx});uv.AddRange(new[]{new Vector2(k/(float)sides,t),new Vector2((k+1)/(float)sides,t),new Vector2((k+1)/(float)sides,u),new Vector2(k/(float)sides,u)});info.AddRange(Enumerable.Repeat(new Vector2(15,2),4));plot.AddRange(Enumerable.Repeat(Vector2.zero,4));host.AddRange(Enumerable.Repeat(Vector2.zero,4));color.AddRange(Enumerable.Repeat(new Color(0,.5f,1,15.5f/16),4));water.AddRange(new[]{i,i+1,i+2,i,i+2,i+3});}}}}
static void Photo(UnityEngine.SceneManagement.Scene s,Vector3 p,Vector3 target,string name)=>typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{s,p,target,name});
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var fs=root.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Fountain_")).ToArray();string backup="FinalEnvironmentRoadBackup/FountainFlowWater-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);
foreach(var f in fs){var m=f.sharedMesh;File.Copy(AssetDatabase.GetAssetPath(m),backup+"/"+m.name+".asset");var p=m.vertices;var info=m.uv2;var colors=m.colors;var plot=new List<Vector2>();var host=new List<Vector2>();m.GetUVs(3,plot);m.GetUVs(4,host);var b=new Build();var remap=new Dictionary<int,int>();int[] ids=m.triangles;foreach(int old in ids.Where(i=>info[i].x<13.5f).Distinct()){remap[old]=b.p.Count;b.p.Add(p[old]);b.n.Add(m.normals[old]);b.uv.Add(m.uv[old]);b.info.Add(info[old]);b.color.Add(colors[old]);b.plot.Add(plot[old]);b.host.Add(host[old]);}for(int i=0;i<ids.Length;i+=3)if(info[ids[i]].x<13.5){var list=info[ids[i]].x>12.5?b.water:b.stone;list.AddRange(new[]{remap[ids[i]],remap[ids[i+1]],remap[ids[i+2]]});}
int streams=0;for(int i=0;i<p.Length;i++){if(info[i].x!=15||colors[i].g>=0)continue;var top=(p[i+2]+p[i+3])*.5f;var bottom=(p[i+20]+p[i+21])*.5f;var d=bottom-top;float width=Vector3.Distance(p[i],p[i+1])*.30f;b.Tube(t=>top+new Vector3(d.x*t*t,d.y*t,d.z*t*t),Mathf.Clamp(width,.015f,.035f),4,6);streams++;i+=23;}
var center=p[Array.FindIndex(info,v=>v.x==13)];var topWater=Enumerable.Range(0,p.Length).Where(i=>info[i].x==13).Select(i=>p[i]).OrderByDescending(v=>v.y).First();float scale=Vector3.Distance(center,p[Array.FindIndex(info,v=>v.x==13)+1])/5.65f;for(int k=0;k<7;k++){float a=k*Mathf.PI*2/7;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));float peak=(k==0?1.5f:1.0f+(k%3)*.16f)*scale;var start=new Vector3(center.x,topWater.y+.015f,center.z)+dir*.055f;float spread=(k==0?.12f:.36f)*scale;b.Tube(t=>start+dir*(spread*t)+Vector3.up*(4*peak*t*(1-t)),.018f*scale,5,10);}
m.Clear();m.SetVertices(b.p);m.SetNormals(b.n);m.SetUVs(0,b.uv);m.SetUVs(1,b.info);m.SetUVs(3,b.plot);m.SetUVs(4,b.host);m.SetColors(b.color);m.subMeshCount=2;m.SetTriangles(b.stone,0);m.SetTriangles(b.water,1);m.RecalculateTangents();m.RecalculateBounds();EditorUtility.SetDirty(m);log.AppendLine(f.name+": "+streams+" curved falling flows; 7 arching top jets; all water uses existing water material; triangles="+m.triangles.Length/3);}
AssetDatabase.SaveAssets();foreach(var f in fs){var p=f.GetComponent<Renderer>().bounds.center;Photo(scene,p+new Vector3(7,4,-9),p,"Water-Flow-"+f.name);Photo(scene,p+new Vector3(4,1,-5),p,"Water-Flow-"+f.name+"-Close");}
var mat=fs[0].GetComponent<Renderer>().sharedMaterials[1];int errors=ShaderUtil.GetShaderMessages(mat.shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);log.AppendLine("SUCCESS both fountains; existing shared water material applied to all water, two submeshes per fountain retained; existing collider unchanged; zero added textures/materials/renderers/lights; shader errors=0; backup="+backup);
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/FountainFlowWaterReport.txt",log.ToString());}}
